
drop policy if exists practice_location_manage on public.practice_location;
create policy practice_location_insert on public.practice_location for insert to authenticated with check(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_location.practice_id and m.active and m.role in('practice_manager','system_admin')));
create policy practice_location_update on public.practice_location for update to authenticated using(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_location.practice_id and m.active and m.role in('practice_manager','system_admin'))) with check(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_location.practice_id and m.active and m.role in('practice_manager','system_admin')));
create policy practice_location_delete on public.practice_location for delete to authenticated using(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_location.practice_id and m.active and m.role in('practice_manager','system_admin')));

