drop policy if exists appointment_request_booking_event_insert on public.appointment_request_event;
create policy appointment_request_booking_event_insert on public.appointment_request_event for insert to authenticated with check(((select auth.jwt())->>'aal')='aal2' and coalesce((select current_setting('request.path',true)),'')='/rpc/create_practice_appointment' and actor_user_id=(select auth.uid()) and exists(select 1 from public.appointment_request r join public.practice_staff_member m on m.practice_id=r.practice_id where r.id=appointment_request_event.appointment_request_id and m.user_id=(select auth.uid()) and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin')));

drop policy if exists practice_appointment_rpc_insert on public.practice_appointment;
create policy practice_appointment_rpc_insert on public.practice_appointment for insert to authenticated with check(((select auth.jwt())->>'aal')='aal2' and coalesce((select current_setting('request.path',true)),'')='/rpc/create_practice_appointment' and created_by=(select auth.uid()) and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_appointment.practice_id and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin')));
drop policy if exists practice_appointment_rpc_update on public.practice_appointment;
create policy practice_appointment_rpc_update on public.practice_appointment for update to authenticated using(((select auth.jwt())->>'aal')='aal2' and coalesce((select current_setting('request.path',true)),'') in('/rpc/reschedule_practice_appointment','/rpc/update_practice_appointment_status') and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_appointment.practice_id and m.active)) with check(((select auth.jwt())->>'aal')='aal2' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=practice_appointment.practice_id and m.active));
drop policy if exists appointment_event_rpc_insert on public.appointment_event;
create policy appointment_event_rpc_insert on public.appointment_event for insert to authenticated with check(((select auth.jwt())->>'aal')='aal2' and coalesce((select current_setting('request.path',true)),'') in('/rpc/create_practice_appointment','/rpc/reschedule_practice_appointment','/rpc/update_practice_appointment_status') and actor_user_id=(select auth.uid()) and exists(select 1 from public.practice_appointment a join public.practice_staff_member m on m.practice_id=a.practice_id where a.id=appointment_event.appointment_id and m.user_id=(select auth.uid()) and m.active));
