drop policy if exists appointment_sequence_rpc_update on public.appointment_sequence;
create policy appointment_sequence_rpc_update on public.appointment_sequence for update to authenticated using(((select auth.jwt())->>'aal')='aal2' and coalesce((select current_setting('request.path',true)),'')='/rpc/create_practice_appointment' and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=appointment_sequence.practice_id and m.active and m.role in('reception','practice_manager','clinical_admin','system_admin'))) with check(true);

drop policy if exists billing_invoice_finance_insert on public.billing_invoice;
create policy billing_invoice_finance_insert on public.billing_invoice for insert to authenticated with check(((select auth.jwt())->>'aal')='aal2' and coalesce((select current_setting('request.path',true)),'')=any(array['/rpc/create_revenue_invoice','/rpc/convert_billing_quote_to_invoice','/rpc/create_practice_custom_invoice','/rpc/create_encounter_private_invoice']) and created_by=(select auth.uid()) and exists(select 1 from public.practice_staff_member m where m.user_id=(select auth.uid()) and m.practice_id=billing_invoice.practice_id and m.active and m.role in('billing','practice_manager','system_admin')));
